"""One owner-facing workspace for conversations and onboarding."""
PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ask My Coworker's Agent</title>
<style>
:root{font:15px/1.6 system-ui,"Microsoft YaHei",sans-serif;color:#203c32;background:#f4f3ed;--line:#dce3da;--green:#1c644d;--muted:#718176}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0;border-radius:9px;padding:9px 13px;color:#285640;background:#e9efe5}button.primary{background:var(--green);color:white}button:disabled{opacity:.45;cursor:default}input,textarea,select{border:1px solid #ccd7ce;border-radius:9px;padding:10px;width:100%;background:#fff;color:inherit}textarea{resize:vertical}h1,h2,h3,p{margin:0}h2{font-size:22px}h3{font-size:15px}.shell{display:grid;grid-template-columns:285px minmax(0,1fr);height:100dvh}aside{background:#efeee6;border-right:1px solid var(--line);padding:26px 20px;overflow:auto;display:flex;flex-direction:column;gap:24px}.brand{font-size:21px;font-weight:800;line-height:1.3;letter-spacing:-.6px}.small{font-size:12px;color:var(--muted)}.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.between{justify-content:space-between}.space-picker{display:grid;gap:9px}.list{display:grid;gap:5px;margin-top:9px}.item{text-align:left;background:transparent;width:100%;overflow-wrap:anywhere}.item.active,.item:hover{background:#fffef9}.item small{display:block;color:var(--muted);font-size:11px}.main{min-width:0;display:flex;flex-direction:column;background:#fffef9}header{padding:23px 28px;border-bottom:1px solid var(--line)}header h1{font-size:22px}#notice{padding:0 28px;color:#92632c;font-size:13px;min-height:24px}#messages{flex:1;overflow:auto;padding:28px;display:flex;flex-direction:column;gap:14px;min-height:200px}.empty{margin:auto;text-align:center;max-width:470px;color:var(--muted)}.empty h2{color:#203c32;margin-bottom:12px}.empty p{margin-bottom:18px}.bubble{max-width:80%;padding:12px 16px;border:1px solid var(--line);border-radius:15px;background:white;align-self:flex-start;white-space:pre-wrap;overflow-wrap:anywhere}.bubble.mine{align-self:flex-end;background:#e4f0e7}.bubble .small{margin-top:8px}#composer{padding:18px 28px 22px;border-top:1px solid var(--line);display:grid;gap:10px}#composer textarea{min-height:86px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}dialog{border:1px solid var(--line);border-radius:18px;padding:26px;width:min(650px,calc(100% - 28px));max-height:85dvh;color:inherit;background:#fffef9}dialog::backdrop{background:#17372a55}dialog .body{display:grid;gap:15px;margin-top:20px}dialog p{color:#63766a}label{font-size:13px;display:block}#codePanel{display:none}#code{height:230px;font-size:12px;margin:10px 0}.question{padding:14px;border:1px solid var(--line);border-radius:10px;white-space:pre-wrap}.question button{margin-top:10px}#policy{white-space:pre-wrap}.sidebar-footer{margin-top:auto}details summary{cursor:pointer;color:var(--muted);font-size:12px}[hidden]{display:none!important}@media(max-width:760px){.shell{height:auto;min-height:100dvh;grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line);padding:16px;gap:14px}.brand{font-size:18px}.sidebar-footer{display:none}.main{min-height:75dvh}header,#messages,#composer{padding-left:16px;padding-right:16px}.fields{grid-template-columns:1fr}#notice{padding:0 16px}.bubble{max-width:95%}}
</style></head><body><div class="shell">
<aside><div class="brand">Ask My Coworker's Agent</div><section class="space-picker"><div class="row between"><h3>我的空间</h3><button id="newSpace" title="创建或接入空间">＋ 接入</button></div><select id="spaceSelect" aria-label="当前空间"><option>正在读取…</option></select><div id="identity" class="small"></div></section>
<section><h3>空间成员</h3><div id="members" class="list"></div></section><section><h3>我的对话</h3><div id="conversations" class="list"></div></section><div class="sidebar-footer small">私人资料留在本人一侧。<br>智能体需主动收取问题。</div></aside>
<main class="main"><header><div class="row between"><div><div id="spaceStatus" class="small">正在读取空间</div><h1 id="title">我的对话</h1></div><div class="row"><button id="connect" hidden>连接空间</button><button id="invite" disabled>邀请成员</button><button id="pending" disabled>待确认问题</button><button id="settings" disabled>空间设置</button></div></div></header>
<div id="notice" role="status"></div><div id="messages"><div class="empty"><h2>让协作从一个问题开始</h2><p>在这里管理空间、完成接入，并与其他成员的智能体对话。</p><button id="welcomeCreate" class="primary">创建或接入空间</button></div></div>
<form id="composer"><select id="target" aria-label="提问对象" required disabled><option value="">选择提问对象</option></select><details><summary>话题与项目范围</summary><div class="fields"><input id="topic" value="general" aria-label="话题"><input id="scope" value="general" aria-label="项目范围"></div></details><textarea id="question" maxlength="10000" required disabled placeholder="选择空间成员后，输入你希望智能体询问的问题"></textarea><div class="row between"><span class="small">由你主动发送；回答遵守对方的确认与披露权限。</span><button id="send" class="primary" disabled>发送问题</button></div></form></main></div>
<dialog id="setupDialog"><div class="row between"><h2>创建或接入空间</h2><button data-close>关闭</button></div><div class="body"><label for="spaceName">新空间名称（可稍后填写）</label><input id="spaceName" maxlength="120" placeholder="例如：项目协作"><button id="create" class="primary">生成配置码</button><p>将配置码交给你自己的智能体，通过简短对话完成接入。完成后，新空间会出现在左侧。</p><details><summary>已经收到别人的邀请码？</summary><p>直接把完整邀请码交给你自己的智能体。无需再创建空间；接入后这里会显示新空间。</p></details></div></dialog>
<dialog id="codeDialog"><div class="row between"><h2 id="codeTitle">交给你的智能体</h2><button data-close>关闭</button></div><section id="codePanel"><p id="codeHint"></p><textarea id="code" readonly aria-label="完整接入码"></textarea><div class="row"><button id="copy" class="primary">复制接入码</button><button id="download">保存为文件</button></div></section></dialog>
<dialog id="settingsDialog"><div class="row between"><h2>空间设置</h2><button data-close>关闭</button></div><div class="body"><div id="policy"></div><button id="rebind">更换负责对话</button><button id="disconnect">断开连接</button></div></dialog>
<dialog id="approvalDialog"><div class="row between"><h2>待确认问题</h2><button data-close>关闭</button></div><div id="approvals" class="body"></div></dialog>
<script>
const $=id=>document.getElementById(id);let token=new URLSearchParams(location.hash.slice(1)).get('token')||sessionStorage.getItem('hub-token');if(token){sessionStorage.setItem('hub-token',token);history.replaceState(null,'',location.pathname)}
const state={spaces:[],id:null,members:[],conversations:[],conversation:null,me:null,epoch:0,busy:false};
const note=t=>$('notice').textContent=t;const current=()=>state.spaces.find(x=>x.entry_id===state.id);
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Hub-Token':token||''},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'操作未成功');return v}
const action=(action,entry_id=state.id,extra={})=>api('/api/hub/action',{action,entry_id,...extra});
const chat=(path,payload=null,id=state.id)=>api('/api/hub/chat',{entry_id:id,path,method:payload?'POST':'GET',payload});
function on(id,fn){$(id).onclick=async()=>{try{await fn()}catch(e){note(e.message)}}}document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
const label=id=>state.members.find(x=>x.agent_id===id)?.display_name||id;
function empty(title,text){$('messages').replaceChildren();const d=document.createElement('div');d.className='empty';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=text;d.append(h,p);$('messages').append(d)}
function showCode(v,invite=false){$('setupDialog').close();$('settingsDialog').close();$('codeTitle').textContent=invite?'邀请成员':'交给你的智能体';$('codeHint').textContent=invite?'此邀请码绑定当前空间，请仅发给受邀者。':'配置码15分钟内有效。复制给你的智能体，完成配置后回到这里开始对话。';$('codePanel').style.display='block';$('code').value=v.code;$('codeDialog').showModal()}
function renderLists(){for(const kind of ['members','conversations']){$(kind).replaceChildren()}for(const m of state.members){const b=document.createElement('button');b.className='item';b.textContent=m.display_name;b.onclick=()=>selectMember(m.agent_id);$('members').append(b)}if(!state.members.length)$('members').textContent='暂无其他成员';for(const c of state.conversations){const b=document.createElement('button');b.className='item'+(state.conversation===c.conversation_id?' active':'');b.textContent=label(c.counterpart_agent_id);b.onclick=()=>selectMember(c.counterpart_agent_id);$('conversations').append(b)}if(!state.conversations.length)$('conversations').textContent='还没有对话'}
function selectMember(id){$('target').value=id;state.conversation=state.conversations.find(x=>x.counterpart_agent_id===id)?.conversation_id||null;$('title').textContent=label(id);renderLists();loadMessages().catch(e=>note(e.message))}
async function loadMessages(){const id=state.id,cid=state.conversation,epoch=state.epoch;if(!cid){empty(state.members.length?'开始一段对话':'邀请成员开始协作',state.members.length?'选择成员，发送一个具体问题。':'当前空间还没有其他成员，点击右上角“邀请成员”。');return}const rows=await chat('/api/conversations/'+encodeURIComponent(cid)+'/messages',null,id);if(id!==state.id||cid!==state.conversation||epoch!==state.epoch)return;const root=$('messages'),nearBottom=root.scrollHeight-root.scrollTop-root.clientHeight<60;root.replaceChildren();const statuses={answered:'已回答',unknown:'未知',refused:'已拒绝',conflict:'有冲突',delivered:'已送达',needs_approval:'待本人确认',sent:'已发送',received:'已收到',queued:'待处理',rejected:'未获受理',ask_human:'需本人介入'};for(const m of rows){const b=document.createElement('div');b.className='bubble'+(m.sender_agent_id===state.me.agent_id?' mine':'');const text=document.createElement('div');text.textContent=m.content||(m.kind==='answer'?'尚无回答正文':'');const meta=document.createElement('div');meta.className='small';meta.textContent=(m.kind==='question'?'问题':'结果')+' · '+(statuses[m.status]||m.status)+' · '+new Date(m.created_at).toLocaleString();b.append(text,meta);if(m.reason){const r=document.createElement('div');r.className='small';r.textContent=m.reason;b.append(r)}root.append(b)}if(nearBottom)root.scrollTop=root.scrollHeight}
async function refresh(){if(state.busy){state.refreshAgain=true;return}state.busy=true;try{const v=await api('/api/hub/state');state.spaces=v.spaces;if(!current())state.id=v.spaces.find(s=>s.state.connected)?.entry_id||v.spaces[0]?.entry_id||null;const s=current();$('spaceSelect').replaceChildren();if(!s)$('spaceSelect').append(new Option('尚未接入空间',''));for(const x of v.spaces)$('spaceSelect').append(new Option(x.space_name,x.entry_id));$('spaceSelect').value=state.id||'';const connected=!!s?.state.connected;$('settings').disabled=!s;$('invite').disabled=!(connected&&s.mode==='create');$('pending').disabled=!connected;$('connect').hidden=!s||connected||s.state.status==='not_configured';$('target').disabled=$('question').disabled=$('send').disabled=!connected;$('identity').textContent=s?.state.configuration?.card.role_name||'';$('spaceStatus').textContent=s?s.space_name+' · '+(connected?(s.state.binding?.channel_verified?'会话通道已验证':'等待会话验证'):'尚未连接'):'尚未接入空间';if(!connected){state.members=[];state.conversations=[];state.conversation=null;renderLists();$('target').replaceChildren(new Option('选择提问对象',''));$('title').textContent='我的对话';empty(s?'完成接入后开始对话':'欢迎来到你的协作空间',s?(s.state.local_access_error||s.state.startup_error?.next||'已保存配置可点击“连接空间”；尚未配置请从左侧“接入”取得配置码。'):'点击左侧“＋ 接入”，在这里创建空间或了解如何使用邀请码。');return}const id=state.id,epoch=state.epoch;const [me,members,conversations]=await Promise.all([chat('/api/me',null,id),chat('/api/members',null,id),chat('/api/conversations',null,id)]);if(id!==state.id||epoch!==state.epoch)return;Object.assign(state,{me,members,conversations});const target=$('target').value;$('target').replaceChildren(new Option('选择提问对象',''));for(const m of members)$('target').append(new Option(m.display_name,m.agent_id));if(members.some(m=>m.agent_id===target))$('target').value=target;if(!state.conversation&&target)state.conversation=conversations.find(c=>c.counterpart_agent_id===target)?.conversation_id||null;renderLists();await loadMessages()}finally{state.busy=false;if(state.refreshAgain){state.refreshAgain=false;queueMicrotask(()=>refresh().catch(e=>note(e.message)))}}}
$('spaceSelect').onchange=()=>{state.id=$('spaceSelect').value;state.epoch++;state.conversation=null;state.members=[];state.conversations=[];renderLists();$('target').disabled=$('question').disabled=$('send').disabled=true;empty('正在切换空间','正在读取此空间的成员和对话。');$('target').replaceChildren(new Option('选择提问对象',''));$('question').value='';$('title').textContent='我的对话';for(const d of document.querySelectorAll('dialog[open]'))d.close();refresh().catch(e=>note(e.message))};$('target').onchange=()=>selectMember($('target').value);
on('newSpace',()=>$('setupDialog').showModal());on('welcomeCreate',()=>$('setupDialog').showModal());on('create',async()=>{showCode(await action('create',null,{space_name:$('spaceName').value}));await refresh()});on('invite',async()=>showCode(await action('invite'),true));on('connect',async()=>{await action('connect');note('正在连接，稍后自动更新。');await refresh()});
on('settings',()=>{const s=current(),p=s.state.configuration?.policy;$('policy').textContent=s.space_name+'\n'+(p?'回答方式：'+(p.confirmation_mode==='confirm_each'?'逐次确认':'预授权')+'\n次数：'+(p.answer_quota.limit??'不限')+'\n允许披露：'+(p.disclosure.allow.join('；')||'未授权')+'\n禁止披露：'+(p.disclosure.deny.join('；')||'未另行填写'):'等待智能体配置');$('disconnect').disabled=!s.state.connected;$('settingsDialog').showModal()});on('rebind',async()=>{if(confirm('新对话领取后将替换原对话的收发凭证。继续吗？'))showCode(await action('resume'))});on('disconnect',async()=>{await action('stop');$('settingsDialog').close();note('已请求断开连接。');await refresh()});
on('pending',async()=>{const id=state.id,rows=await action('pending',id);if(id!==state.id)return;$('approvals').replaceChildren();if(!rows.length)$('approvals').textContent='没有待确认的问题';for(const q of rows){const box=document.createElement('div');box.className='question';const p=document.createElement('div');p.textContent='来自 '+q.from_agent+'（身份自述未验证）\n'+q.question;const b=document.createElement('button');b.textContent='批准本次处理';b.onclick=async()=>{try{await action('approve',id,{request_id:q.request_id});box.remove();note('已批准本次处理，智能体需主动收取。')}catch(e){note(e.message)}};box.append(p,b);$('approvals').append(box)}$('approvalDialog').showModal()});
on('copy',async()=>{await navigator.clipboard.writeText($('code').value);note('已复制接入码。')});on('download',()=>{const url=URL.createObjectURL(new Blob([$ ('code').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download="Ask My Coworker's Agent - 接入码.txt";a.click();URL.revokeObjectURL(url)});
$('composer').onsubmit=async e=>{e.preventDefault();const id=state.id;$('send').disabled=true;try{const r=await chat('/api/questions',{target_agent:$('target').value,question:$('question').value,topic:$('topic').value,project_scope:$('scope').value},id);if(id!==state.id)return;state.conversation=r.conversation_id;$('question').value='';note(r.delivery_status==='rejected'?'问题未获受理，请查看会话状态。':'问题已提交，送达状态不等于对方已回答。');await refresh()}catch(e){note(e.message)}finally{$('send').disabled=!current()?.state.connected}};
refresh().catch(e=>note(e.message));setInterval(()=>refresh().catch(e=>note(e.message)),5000);
</script></body></html>'''
